INSERT INTO miss_jeeves_answer_bank_versions (answer_version_id, answer_key, version, canonical_question, answer_text, sources_json, related_laidies_json, model_version, source_policy_version, checked_at, expires_at, recheck_triggers_json, visibility, approved_for_example, supersedes_version_id, answer_fingerprint, source_digest, aliases_digest, review_fingerprint, created_at) VALUES ('mjab_7a9690935a2f46688d6860eeee3f144e','environment-ai',1,'Is AI bad for the environment?','Yes. AI has environmental costs: the computers behind it need electricity, cooling and physical equipment. How large those costs are depends on what the AI does, how often it runs and where its computers are located.

Electricity is part of the story. Training AI and generating answers both use power. The emissions associated with that power depend on how it is generated. The IEA reports that electricity use at AI-focused data centres rose 50% in 2025—even as individual AI tasks became more efficient. Both can be true: each task can use less energy while growing demand pushes the total up.

Water and hardware matter too. Data centres can use water for cooling; the consequences differ between places with plentiful water and places already facing shortages. Manufacturing computers also requires raw materials, and discarded equipment creates electronic waste. These are costs of the physical infrastructure AI shares with other digital services, not measurements of AI alone.

That is why a single “one prompt uses this much” figure is misleading when applied to every AI interaction. A short text answer and generating video involve very different amounts of computing. The model, task and electricity supply all matter.

AI can also help with environmental work, such as managing electricity grids. Those benefits need to be demonstrated for the particular use; they do not automatically cancel the costs of building and running it.

You do not need to calculate a personal footprint to understand the issue. A useful test of a “greener AI” claim is whether it explains total consumption, local water impacts and hardware—not just how efficient one task has become.','[{"title":"IEA · Key Questions on Energy and AI (2026)","url":"https://www.iea.org/reports/key-questions-on-energy-and-ai/executive-summary","contentDigest":"b9a50b5cc373d42dd2591e62174cd3d8821ab5e5183c84b59a0923a00632f8f6"},{"title":"UN Trade and Development · Digital Economy Report (2024): water and hardware","url":"https://unctad.org/system/files/official-document/der2024_overview_en.pdf","contentDigest":"f25df0a8c6c1df7887d2f84989ad278d7d0186c4c6275e511b80ea2433c9640a"}]','[]','gpt-5.6-sol pilot; GPT-6 Astra editorial revision','2026-09-07.environment.1','2026-09-07T21:46:55.677Z','2026-09-08T21:46:55.680Z','["Exact sources checked before reuse; failure or changed content withholds answer","24hour expiry requires substantive current-evidence review; never automatic date renewal","Only reviewed exact aliases; changed circumstances do not reuse"]','internal_reusable',1,NULL,'52382774c2377d9ba55a4b2a7eb0576eb62c70fde7c62a664e9e980d241bd20e','5aa4bcb2b2d203ed8c10b89d57bb3f9eda86e7b97e262f627145fcf07db3887d','141a31ead49ddcce4ab4748d44f78a6a82134d2dee1465824799f52423ef86fd','76323447f9f7e68710c6a9b12023b929024a3c42c5452e075ab9dc762140d0c2','2026-09-07T21:52:24.140Z');
